import{_ as d,o as e,c as o,a2 as a}from"./chunks/framework.CBWbbCW8.js";const u=JSON.parse('{"title":"账户概览","description":"","frontmatter":{},"headers":[],"relativePath":"account/overview.md","filePath":"account/overview.md","lastUpdated":1784973959000}'),r={name:"account/overview.md"};function c(i,t,l,s,n,h){return e(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="账户概览" tabindex="-1">账户概览 <a class="header-anchor" href="#账户概览" aria-label="Permalink to &quot;账户概览&quot;">​</a></h1><p>DouDi.ai 的账户中心围绕余额、订阅、发票和个人资料展开。根据公开站点状态和前端模块信息，当前个人中心包含 <code>Wallet</code>、<code>Invoice Center</code>、<code>Affiliate Commission</code>、<code>Profile</code> 等入口；订阅管理相关能力也存在于站点模块中。</p><h2 id="常用入口" tabindex="-1">常用入口 <a class="header-anchor" href="#常用入口" aria-label="Permalink to &quot;常用入口&quot;">​</a></h2><table tabindex="0"><thead><tr><th>功能</th><th>入口</th><th>用途</th></tr></thead><tbody><tr><td>钱包余额</td><td><code>Wallet</code></td><td>查看余额、充值、钱包流水和支付结果。</td></tr><tr><td>我的订阅</td><td><code>My Subscriptions</code></td><td>查看已购买订阅、有效期、套餐权益和订阅记录。</td></tr><tr><td>发票中心</td><td><code>Invoice Center</code></td><td>查看付费订单关联的发票信息。</td></tr><tr><td>个人资料</td><td><code>Profile</code></td><td>管理个人资料、安全设置和账号信息。</td></tr><tr><td>调用日志</td><td><code>Usage Logs</code></td><td>核对 API 调用产生的消耗。</td></tr></tbody></table><h2 id="余额与订阅的关系" tabindex="-1">余额与订阅的关系 <a class="header-anchor" href="#余额与订阅的关系" aria-label="Permalink to &quot;余额与订阅的关系&quot;">​</a></h2><p>DouDi.ai 支持钱包余额体系。公开前端文案显示，订阅可以通过余额购买，且可能支持订阅优惠码。也就是说你可以先充值到钱包，再用余额购买订阅套餐。</p><p>常见流程是：</p><ol><li>登录 DouDi.ai。</li><li>到 <code>Wallet</code> 充值余额。</li><li>到 <code>My Subscriptions</code> 或订阅入口选择套餐。</li><li>使用余额或可用支付方式完成购买。</li><li>回到 <code>Usage Logs</code> 和 <code>Wallet</code> 查看消耗与余额变化。</li></ol><h2 id="当前公开可核验信息" tabindex="-1">当前公开可核验信息 <a class="header-anchor" href="#当前公开可核验信息" aria-label="Permalink to &quot;当前公开可核验信息&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>当前公开值</th></tr></thead><tbody><tr><td>服务地址</td><td><code>https://doudi.ai</code></td></tr><tr><td>额度展示类型</td><td><code>USD</code></td></tr><tr><td>额度单位字段</td><td><code>500000</code></td></tr><tr><td>美元汇率字段</td><td><code>7.3</code></td></tr><tr><td>是否按货币展示额度</td><td>是</td></tr><tr><td>在线充值模块</td><td>已在个人中心模块中启用</td></tr><tr><td>发票中心模块</td><td>已在个人中心模块中启用</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>订阅套餐列表、套餐价格、具体权益和优惠码属于登录后动态数据，本文档不写死具体价格。购买前请以控制台实时显示为准。</p></div>',11)])])}const b=d(r,[["render",c]]);export{u as __pageData,b as default};
